class Solution {
    public String mostCommonWord(String paragraph,String[] banned){
        Set<String> blocked=new HashSet<>(Arrays.asList(banned));
        Map<String,Integer> frequency=new HashMap<>();
        String answer="";
        int best=0;
        for(String word:paragraph.toLowerCase().split("[^a-z]+")){
            if(word.isEmpty()||blocked.contains(word))continue;
            int count=frequency.merge(word,1,Integer::sum);
            if(count>best){
                best=count;
                answer=word;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun mostCommonWord(paragraph:String,banned:Array<String>):String{
        val blocked=banned.toSet();
        val frequency=mutableMapOf<String,Int>();
        var answer="";
        var best=0;
        for(word in paragraph.lowercase().split(Regex("[^a-z]+"))){
            if(word.isEmpty()||word in blocked)continue;
            val count=(frequency[word]?:0)+1;
            frequency[word]=count;
            if(count>best){
                best=count;
                answer=word
            }
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: string mostCommonWord(string paragraph,vector<string>& banned){
        unordered_set<string> blocked(banned.begin(),banned.end());
        unordered_map<string,int> frequency;
        string answer,word;
        int best=0;
        paragraph+=' ';
        for(char c:paragraph){
            if(isalpha(c))word+=tolower(c);
            else if(!word.empty()){
                if(!blocked.count(word)&&++frequency[word]>best){
                    best=frequency[word];
                    answer=word;
                }
                word.clear();
            }
        }
        return answer;
    }
};
